import React, { useState, useEffect } from "react";
import { Link } from "react-router-dom";
import axios from "axios";

const Menu = () => {
  const [selectedMenu, setSelectedMenu] = useState(0);
  const [isProfileDropdownOpen, setIsProfileDropdownOpen] = useState(false);
  const [username, setUsername] = useState("User");

  // Backend se user details lana
  useEffect(() => {
    const verifyUser = async () => {
      try {
        const { data } = await axios.get("http://localhost:3002/user", {
          withCredentials: true,
        });
        if (data.status) {
          setUsername(data.username);
        }
      } catch (err) {
        console.log(err);
      }
    };
    verifyUser();
  }, []);

  const handleMenuClick = (index) => {
    setSelectedMenu(index);
  };

  const handleProfileClick = () => {
    setIsProfileDropdownOpen(!isProfileDropdownOpen);
  };

  const handleLogout = async () => {
    try {
      await axios.post(
        "http://localhost:3002/logout",
        {},
        { withCredentials: true }
      );
      window.location.href = "http://localhost:3000";
    } catch (error) {
      console.log("Error logging out", error);
    }
  };

  // Styles (Jo image jaisa dikhayenge)
  const menuContainerStyle = {
    display: "flex",
    justifyContent: "space-between", // Logo Left, Menu Right
    alignItems: "center",
    padding: "0 50px", // Side gap
    height: "70px",
    backgroundColor: "#fff",
    borderBottom: "1px solid #eee",
    boxShadow: "0 1px 2px rgba(0,0,0,0.03)",
    position: "sticky",
    top: 0,
    zIndex: 1000
  };

  const linkStyle = {
    textDecoration: "none",
    color: "#444",
    fontSize: "14px",
    fontWeight: "400",
    transition: "color 0.3s"
  };

  const activeLinkStyle = {
    ...linkStyle,
    color: "#db4d34", // Active color
    fontWeight: "500"
  };

  return (
    <div style={menuContainerStyle}>
      {/* LEFT SIDE: LOGO */}
      <img src="logo.png" style={{ width: "25px", cursor: "pointer" }} alt="Logo" />

      {/* RIGHT SIDE: LINKS & PROFILE */}
      <div style={{ display: "flex", alignItems: "center", gap: "30px" }}>

        {/* Menu Links */}
        <ul style={{ display: "flex", listStyle: "none", gap: "25px", margin: 0, padding: 0 }}>
          <li>
            <Link style={{ textDecoration: "none" }} to="/" onClick={() => handleMenuClick(0)}>
              <p style={selectedMenu === 0 ? activeLinkStyle : linkStyle}>Dashboard</p>
            </Link>
          </li>
          <li>
            <Link style={{ textDecoration: "none" }} to="/orders" onClick={() => handleMenuClick(1)}>
              <p style={selectedMenu === 1 ? activeLinkStyle : linkStyle}>Orders</p>
            </Link>
          </li>
          <li>
            <Link style={{ textDecoration: "none" }} to="/holdings" onClick={() => handleMenuClick(2)}>
              <p style={selectedMenu === 2 ? activeLinkStyle : linkStyle}>Holdings</p>
            </Link>
          </li>
          <li>
            <Link style={{ textDecoration: "none" }} to="/positions" onClick={() => handleMenuClick(3)}>
              <p style={selectedMenu === 3 ? activeLinkStyle : linkStyle}>Positions</p>
            </Link>
          </li>
          <li>
            <Link style={{ textDecoration: "none" }} to="/funds" onClick={() => handleMenuClick(4)}>
              <p style={selectedMenu === 4 ? activeLinkStyle : linkStyle}>Funds</p>
            </Link>
          </li>
          <li>
            <Link style={{ textDecoration: "none" }} to="/apps" onClick={() => handleMenuClick(6)}>
              <p style={selectedMenu === 6 ? activeLinkStyle : linkStyle}>Apps</p>
            </Link>
          </li>
        </ul>

        {/* Separator Line */}
        <div style={{ height: "25px", width: "1px", backgroundColor: "#e0e0e0" }}></div>

        {/* Profile Section */}
        <div 
          onClick={handleProfileClick} 
          style={{ display: "flex", alignItems: "center", gap: "10px", cursor: "pointer", position: "relative" }}
        >
          <div style={{
             width: "30px",
             height: "30px",
             borderRadius: "50%",
             backgroundColor: "#f3e8ff",
             color: "#8e44ad",
             display: "flex",
             justifyContent: "center",
             alignItems: "center",
             fontSize: "11px",
             fontWeight: "600"
          }}>
            {username && username.length > 0 ? username[0].toUpperCase() : "U"}
          </div>
          <p style={{ margin: 0, fontSize: "11px", color: "#666", fontWeight: "500", textTransform: "uppercase" }}>
            {username}
          </p>

          {/* Dropdown */}
          {isProfileDropdownOpen && (
            <div style={{
              position: "absolute",
              top: "140%",
              right: 0,
              backgroundColor: "white",
              border: "1px solid #ccc",
              borderRadius: "4px",
              padding: "10px",
              width: "100px",
              boxShadow: "0px 4px 6px rgba(0,0,0,0.1)",
              zIndex: 1000,
              textAlign: "center"
            }}>
              <div
                onClick={handleLogout}
                style={{ cursor: "pointer", color: "#d9534f", fontWeight: "600" }}
              >
                Logout
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Menu;
